-- about-us (replace the draft blocks)
do $mig$
declare pid uuid;
begin
  select id into pid from public.pages where slug = 'about-us' and locale = 'en';
  if pid is null then raise exception 'page about-us does not exist'; end if;
  if exists (select 1 from public.page_blocks_backup_20261102 where page_id = pid) then raise notice 'skipped about-us: already applied'; return; end if;
  if not (select count(*) = 2 and coalesce(max(updated_at) = '2026-09-11 13:41:39.659004+00'::timestamptz, false) from public.page_blocks where page_id = pid) then
    raise notice 'skipped about-us: its draft changed since the dry-run was reviewed'; return;
  end if;
  insert into public.page_blocks_backup_20261102 select b.*, now() from public.page_blocks b where b.page_id = pid;
  delete from public.page_blocks where page_id = pid;
  insert into public.page_blocks (page_id, type, position, is_visible, data) values
    (pid, 'hero_page', 10, true, $json${"background":"navy","title":"About Us"}$json$::jsonb),
    (pid, 'columns', 20, true, $json${"background":"cream","columns":[{"type":"text","heading":"Vision","body":"OSI's vision is to become one of the market leaders in providing innovative solutions with new technology in areas such as sales and service of Filtration/Sand Control, Gas Separation, Chemical Treatment, and Downhole Pumps in support of applications for the Oil and Gas Industry."},{"type":"text","heading":"Mission","body":"Odessa Separator Inc. offers Sales and service of Filtration/Sand Control, Gas Separation, Chemical Treatment and Downhole Pumps in support of applications for the Oil and Gas Industry. We are dedicated to focusing our efforts in satisfying our customers' needs with the safety of processes and protection of the environment by performing operations with an emphasis on quality and integrity in each department."}]}$json$::jsonb),
    (pid, 'rich_text', 30, true, $json${"background":"cream","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"History"}]},{"type":"paragraph","content":[{"type":"text","text":"Odessa Separator Inc. was founded by Bert Frost in 1995 as a sole proprietorship. As the company continued to grow, it was officially incorporated in 2001. Since its inception, OSI has been committed to delivering innovative downhole solutions for artificial lift systems, including SRP, ESP, PCP, Gas Lift, and other production technologies. Guided by a culture of innovation and customer commitment, the company has consistently developed technologies that improve production efficiency, extend equipment life, and transform the way operators optimize oil recovery."}]},{"type":"paragraph","content":[{"type":"text","text":"The company was originally established as a wholesale supplier of downhole gas separators and sand screens for the oil and gas industry. During its early years, the product line was continuously refined, with sand control solutions becoming a primary focus of the business."}]},{"type":"paragraph","content":[{"type":"text","text":"By 1998, Odessa Separator had established a strong presence in the market. The company experienced significant growth throughout the following years, culminating in a major expansion in 2006 when OSI introduced an innovative line of downhole chemical treatment and delivery solutions, broadening its portfolio beyond separation and sand control technologies."}]},{"type":"paragraph","content":[{"type":"text","text":"In 2013, OSI expanded its operations across the United States by opening locations in Montana, North Dakota, San Antonio, New Mexico, and Oklahoma. Building on that momentum, the company entered the Latin American market in 2014 by establishing Odessa Separator Inc. S.A.S. in Colombia."}]},{"type":"paragraph","content":[{"type":"text","text":"Starting with a single employee, OSI Colombia successfully introduced the company's product line into more than 150 wells by 2016. Today, the Colombian operation has grown into a highly qualified technical and commercial team that supports customers throughout Colombia while expanding OSI's presence across Latin America. Through its regional operations, the company continues to strengthen its footprint in Ecuador, Mexico, Brazil, and Argentina, delivering innovative artificial lift and downhole production solutions tailored to the needs of each market."}]},{"type":"paragraph","content":[{"type":"text","text":"Throughout the years, OSI has remained focused on research, engineering, and product development. Its continuous investment in innovation has resulted in technologies that have positively impacted the oil and gas industry by improving production performance, increasing equipment runtime, reducing operating costs, and optimizing downhole production processes. These innovations have helped redefine how operators maximize oil recovery while improving the efficiency and reliability of artificial lift systems."}]},{"type":"paragraph","content":[{"type":"text","text":"In 2025, Odessa Separator Inc. reached another significant milestone by expanding its operations through the creation of the OSI Rod Pump Division, headquartered in Midland, Texas. This new division was established to provide specialized Sucker Rod Pump solutions, strengthening OSI's position within the mechanical pumping market and expanding the company's portfolio of technologies and services. The addition of the OSI Rod Pump Division enables the company to deliver more comprehensive artificial lift solutions while continuing to meet the evolving needs of operators across North America and international markets."}]},{"type":"paragraph","content":[{"type":"text","text":"Today, Odessa Separator Inc. continues to lead through innovation, engineering excellence, and technical expertise. As the company celebrates more than three decades of growth, it remains committed to developing next-generation technologies that improve production performance, optimize artificial lift operations, and create lasting value for customers around the world."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"QMS Policy"}]},{"type":"paragraph","content":[{"type":"text","text":"Through this policy, ODESSA SEPARATOR INC. (OSI) is committed to fulfilling customer and other applicable requirements by continuously using innovative technology, providing our customer with excellent services, and exceeding our customer’s demands. This will be accomplished through continually improving our services and internal processes and fulfilling our Quality Objectives as defined in our Quality System."}]},{"type":"paragraph","content":[{"type":"text","text":"We foster a culture of continuous improvement through audits, risk assessments, and active employee engagement. By offering training, clear communication, and opportunities to participate in QMS initiatives, we empower our employees to maintain the highest quality standards. We promote teamwork and accountability to drive excellence across all operations."}]},{"type":"paragraph","content":[{"type":"text","text":"Gustavo Gonzalez"}]},{"type":"paragraph","content":[{"type":"text","text":"CEO – Odessa Separator Inc"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Core Values"}]},{"type":"paragraph","content":[{"type":"text","text":"Growth - Improvement - Consistency"}]},{"type":"paragraph","content":[{"type":"text","text":"Creativity - Justice - Respectful"}]}]}}$json$::jsonb),
    (pid, 'button_group', 40, true, $json${"background":"cream","alignment":"left","buttons":[{"label":"QMS Policy, Mission, Vision and Core values","href":"https://ovuhuridnalxnzwggzru.supabase.co/storage/v1/object/public/media/legacy-pages/7795814fe2-1ac9e9_0a271508a7ad480a8d1b830043879e9d.pdf"}]}$json$::jsonb);
  update public.pages set draft_version = draft_version + 1, updated_at = now() where id = pid;
end
$mig$;

